package com.orderflow;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import com.orderflow.model.Order;
import com.orderflow.model.OrderProcessingResult;
import com.orderflow.service.OrderProcessor;

public class App {
    public String getGreeting() {
        return "Hello World!";
    }

    public static void main(String[] args) {
        //1
        List<Order> orders = List.of(
            new Order(101L, 10L, new BigDecimal("50.00")),
            new Order(102L, 20L, new BigDecimal("80.00")),
            new Order(103L, 10L, new BigDecimal("30.00")),
            new Order(101L, 10L, new BigDecimal("50.00")),
            new Order(104L, 20L, new BigDecimal("20.00"))
        );

        OrderProcessor processor = new OrderProcessor();
        OrderProcessingResult result = processor.groupByCustomer(orders);
        Map<Long, List<Order>> grouped = result.getOrdersByCustomer();                

        for (Map.Entry<Long, List<Order>> entry : grouped.entrySet()) {
            System.out.println("Customer: " + entry.getKey());

            for (Order order : entry.getValue()) {
                System.out.println("  Order: " + order.getId());
            }
        }

        //2
        Order first = new Order(1L, 100L, new BigDecimal("50.00"));
        Order duplicate = new Order(1L, 100L, new BigDecimal("80.00"));
        Order another = new Order(2L, 100L, new BigDecimal("50.00"));

        Set<Order> orders2Set = new HashSet<>();

        System.out.println(orders2Set.add(first));
        System.out.println(orders2Set.add(duplicate));
        System.out.println(orders2Set.add(another));
        System.out.println(orders2Set.size());

        //3
        Map<Long, Set<Order>> ordersByCustomer = new HashMap<>();
  
        List<Order> orders3List = List.of(
            new Order(1L, 100L, new BigDecimal("50.00")),
            new Order(1L, 100L, new BigDecimal("80.00")),
            new Order(2L, 100L, new BigDecimal("30.00")),
            new Order(3L, 200L, new BigDecimal("90.00"))
        );

        for (Order order : orders3List) {
            Long customerCode = order.getCustomerCode();

            Set<Order> ordersForCustomer  = ordersByCustomer.get(customerCode);
            if (ordersForCustomer  == null) {
                ordersForCustomer = new HashSet<>();
                ordersByCustomer.put(customerCode, ordersForCustomer);
            }

            ordersForCustomer .add(order);
        }


    }
}
